import{_ as t,a as i}from"./chunks/ptz-2.0a-OLPXN.js";import{_ as o,o as r,c as l,a5 as n,j as e}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"PTZ GUI","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/ptz-gui.md","filePath":"ko/manual/gui/ptz-gui.md","lastUpdated":1785806767000}'),c={name:"ko/manual/gui/ptz-gui.md"};function s(d,a,p,u,m,g){return r(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="ptz-gui" tabindex="-1">PTZ GUI <a class="header-anchor" href="#ptz-gui" aria-label="Permalink to &quot;PTZ GUI&quot;">​</a></h1><p>PTZ 카메라(옵션) 장착 시 RBQGUI에서 카메라 방향(Pan/Tilt), 줌, 영상 모드(컬러/열화상) 등을 제어할 수 있습니다.</p><h2 id="_1-화면-진입" tabindex="-1">1) 화면 진입 <a class="header-anchor" href="#_1-화면-진입" aria-label="Permalink to &quot;1) 화면 진입&quot;">​</a></h2><ol><li>RBQGUI를 실행하고 로봇과 연결합니다.</li><li>카메라 화면으로 이동한 뒤 PTZ 제어 화면을 엽니다.</li><li>PTZ가 정상 연결되면 하단 제어 영역을 사용할 수 있습니다.</li></ol><figure style="margin-top:1rem;text-align:center;"><img src="'+t+'" alt="PTZ GUI 화면" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">PTZ GUI 메인 화면</figcaption></figure><h2 id="_2-기본-조작-pan-tilt" tabindex="-1">2) 기본 조작 (Pan/Tilt) <a class="header-anchor" href="#_2-기본-조작-pan-tilt" aria-label="Permalink to &quot;2) 기본 조작 (Pan/Tilt)&quot;">​</a></h2><ul><li>화면의 PTZ 조작 영역(가상 조이스틱)을 드래그하여 카메라를 좌/우(Pan), 상/하(Tilt)로 움직입니다.</li><li>손을 놓으면 입력이 정지되며, 필요 시 다시 드래그해 미세 조정합니다.</li><li>빠른 조작보다 작은 입력으로 천천히 움직이면 목표 지점을 맞추기 쉽습니다.</li></ul><h2 id="_3-줌-제어" tabindex="-1">3) 줌 제어 <a class="header-anchor" href="#_3-줌-제어" aria-label="Permalink to &quot;3) 줌 제어&quot;">​</a></h2><p>하단 <code>Zoom</code> 버튼으로 광학 배율을 즉시 변경할 수 있습니다.</p><ul><li><code>1x</code>, <code>3x</code>, <code>8x</code>, <code>16x</code>, <code>32x</code>: 고정 배율 선택</li><li><code>Center</code>: 카메라 방향을 기본 중심 위치로 복귀</li></ul><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="PTZ 줌 및 스위치 제어" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">줌 버튼 및 스위치 영역</figcaption></figure><h2 id="_4-영상-모드·조이스틱" tabindex="-1">4) 영상 모드·조이스틱 <a class="header-anchor" href="#_4-영상-모드·조이스틱" aria-label="Permalink to &quot;4) 영상 모드·조이스틱&quot;">​</a></h2><p>하단 오른쪽에서 <strong>열화상/컬러</strong> 전환과 <strong>가상 조이스틱</strong> 표시를 제어합니다.</p><ul><li><strong>Thermal / Color</strong>: 열화상(<code>Thermal</code>)과 컬러(<code>Color</code>) 영상 전환</li><li><strong>조이스틱 아이콘</strong>(화면 오른쪽 중앙): 터치 시 가상 조이스틱 패널 표시·숨김</li></ul><h2 id="_5-종료" tabindex="-1">5) 종료 <a class="header-anchor" href="#_5-종료" aria-label="Permalink to &quot;5) 종료&quot;">​</a></h2><p>우측 상단 <code>Exit</code> 버튼으로 PTZ 화면을 종료하고 기본 GUI 화면으로 복귀합니다.</p><h2 id="동작-예시-영상" tabindex="-1">동작 예시 영상 <a class="header-anchor" href="#동작-예시-영상" aria-label="Permalink to &quot;동작 예시 영상&quot;">​</a></h2>',17),e("figure",{style:{"text-align":"center",margin:"1rem 0"}},[e("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/ThilVsiWMfc",title:"PTZ 기본 조작",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"PTZ 기본 조작")],-1)])])}const P=o(c,[["render",s]]);export{f as __pageData,P as default};
